import { getCurrentCell, getCurrentTable, getCellRange, getCellPosition } from '../core/Tables';

const SELECTED_CLASS = 'omar-text-editor-cell-selected';

// Tracks a rectangular multi-cell selection within a single table: mousedown
// on a cell anchors it, mousemove over a different cell extends the
// rectangle (highlighted via SELECTED_CLASS), mouseup commits it. A plain
// click (mousedown/mouseup on the same cell, no drag) leaves no selection so
// normal caret placement isn't disturbed. Also renders column/row header
// select strips along a hovered table's top/left edge; clicking a strip
// segment selects that whole column/row through the same state, so
// selection-scoped context menu actions work uniformly either way.
export class TableCellSelection {
  private table: HTMLTableElement | null = null;
  private anchor: HTMLTableCellElement | null = null;
  private selected: HTMLTableCellElement[] = [];
  private dragging = false;
  private onChangeCb: (() => void) | null = null;

  private colStrips: HTMLElement[] = [];
  private rowStrips: HTMLElement[] = [];
  private hoveredTable: HTMLTableElement | null = null;

  constructor(private root: HTMLElement) {
    root.addEventListener('mousedown', this.handleMouseDown);
    root.addEventListener('mouseover', this.handleMouseOver);
    document.addEventListener('mouseup', this.handleMouseUp);
    document.addEventListener('mousedown', this.handleOutsideMouseDown, true);
    document.addEventListener('keydown', this.handleKeydown);
    root.addEventListener('mousemove', this.handleHoverForStrips);
    root.addEventListener('input', () => this.refreshStrips());
  }

  onChange(cb: () => void): void {
    this.onChangeCb = cb;
  }

  getSelectedCells(): HTMLTableCellElement[] {
    return this.selected.slice();
  }

  getSelectedTable(): HTMLTableElement | null {
    return this.table;
  }

  private handleMouseDown = (e: MouseEvent): void => {
    const cell = getCurrentCell(e.target as Node);
    if (!cell) {
      this.clear();
      return;
    }
    const table = getCurrentTable(cell);
    if (!table) return;

    this.clear();
    this.table = table;
    this.anchor = cell;
    this.dragging = true;
  };

  private handleMouseOver = (e: MouseEvent): void => {
    if (!this.dragging || !this.anchor || !this.table) return;
    const cell = getCurrentCell(e.target as Node);
    if (!cell || getCurrentTable(cell) !== this.table) return;

    if (cell === this.anchor) {
      this.applyHighlight([]);
      return;
    }
    const range = getCellRange(this.table, this.anchor, cell);
    this.applyHighlight(range);
  };

  private handleMouseUp = (): void => {
    if (!this.dragging) return;
    this.dragging = false;
    // A single-cell "range" (no real drag) is not a multi-selection.
    if (this.selected.length <= 1) {
      this.clearHighlightOnly();
    } else {
      this.onChangeCb?.();
    }
  };

  private handleOutsideMouseDown = (e: MouseEvent): void => {
    if (this.selected.length === 0) return;
    const target = e.target as Node;
    if (this.root.contains(target)) return;
    this.clear();
  };

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape' && this.selected.length > 0) {
      this.clear();
    }
  };

  private applyHighlight(cells: HTMLTableCellElement[]): void {
    this.selected.forEach((c) => c.classList.remove(SELECTED_CLASS));
    this.selected = cells;
    this.selected.forEach((c) => c.classList.add(SELECTED_CLASS));
  }

  private clearHighlightOnly(): void {
    this.selected.forEach((c) => c.classList.remove(SELECTED_CLASS));
    this.selected = [];
  }

  // Selects every cell belonging to the given column/row index, feeding the
  // same highlight state used by drag-selection.
  selectColumn(table: HTMLTableElement, colIndex: number): void {
    this.clear();
    this.table = table;
    const cells: HTMLTableCellElement[] = [];
    table.querySelectorAll('tr').forEach((row) => {
      Array.from(row.children).forEach((child) => {
        const cell = child as HTMLTableCellElement;
        const pos = getCellPosition(table, cell);
        if (pos && pos.col === colIndex) cells.push(cell);
      });
    });
    this.applyHighlight(cells);
    this.onChangeCb?.();
  }

  selectRow(table: HTMLTableElement, rowIndex: number): void {
    this.clear();
    this.table = table;
    const row = table.querySelectorAll('tr')[rowIndex];
    if (!row) return;
    this.applyHighlight(Array.from(row.children) as HTMLTableCellElement[]);
    this.onChangeCb?.();
  }

  clear(): void {
    this.clearHighlightOnly();
    this.table = null;
    this.anchor = null;
    this.dragging = false;
  }

  // --- header select strips ---

  private handleHoverForStrips = (e: MouseEvent): void => {
    const table = (e.target as Element).closest('table') as HTMLTableElement | null;
    if (table !== this.hoveredTable) {
      this.hoveredTable = table;
      this.refreshStrips();
    }
  };

  private refreshStrips(): void {
    this.clearStrips();
    if (!this.hoveredTable || !this.root.contains(this.hoveredTable)) return;
    this.buildStrips(this.hoveredTable);
  }

  private clearStrips(): void {
    this.colStrips.forEach((s) => s.remove());
    this.rowStrips.forEach((s) => s.remove());
    this.colStrips = [];
    this.rowStrips = [];
  }

  private buildStrips(table: HTMLTableElement): void {
    const firstRow = table.querySelector('tr');
    if (!firstRow) return;
    const parent = table.parentElement;
    if (!parent) return;
    parent.style.setProperty('position', 'relative');

    const parentRect = parent.getBoundingClientRect();
    const tableRect = table.getBoundingClientRect();
    const colCount = firstRow.children.length;

    for (let c = 0; c < colCount; c++) {
      const cell = firstRow.children[c] as HTMLElement;
      const cellRect = cell.getBoundingClientRect();
      const strip = document.createElement('div');
      strip.className = 'omar-text-editor-col-select-strip';
      strip.style.left = `${cellRect.left - parentRect.left}px`;
      strip.style.top = `${tableRect.top - parentRect.top - 8}px`;
      strip.style.width = `${cellRect.width}px`;
      strip.addEventListener('mousedown', (e) => {
        e.preventDefault();
        this.selectColumn(table, c);
      });
      parent.appendChild(strip);
      this.colStrips.push(strip);
    }

    const rows = table.querySelectorAll('tr');
    rows.forEach((row, r) => {
      const rowRect = row.getBoundingClientRect();
      const strip = document.createElement('div');
      strip.className = 'omar-text-editor-row-select-strip';
      strip.style.top = `${rowRect.top - parentRect.top}px`;
      strip.style.left = `${tableRect.left - parentRect.left - 8}px`;
      strip.style.height = `${rowRect.height}px`;
      strip.addEventListener('mousedown', (e) => {
        e.preventDefault();
        this.selectRow(table, r);
      });
      parent.appendChild(strip);
      this.rowStrips.push(strip);
    });
  }

  destroy(): void {
    this.root.removeEventListener('mousedown', this.handleMouseDown);
    this.root.removeEventListener('mouseover', this.handleMouseOver);
    document.removeEventListener('mouseup', this.handleMouseUp);
    document.removeEventListener('mousedown', this.handleOutsideMouseDown, true);
    document.removeEventListener('keydown', this.handleKeydown);
    this.root.removeEventListener('mousemove', this.handleHoverForStrips);
    this.clearStrips();
    this.clear();
  }
}
