// Original list engine: toggling a paragraph/selection into/out of a
// <ul>/<ol>, nesting via Tab/Shift+Tab, and Enter/Backspace behavior that
// matches common rich-text-editor conventions.

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestor(root: HTMLElement, node: Node, tags: string[]): HTMLElement | null {
  let current: Node | null = node;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE && tags.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

function findBlock(root: HTMLElement, node: Node): HTMLElement | null {
  return findAncestor(root, node, ['p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'blockquote']);
}

function setCaretAt(node: Node, offset: number): void {
  const range = document.createRange();
  range.setStart(node, offset);
  range.setEnd(node, offset);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

// Toggles the block containing the caret into/out of a list of type
// `listTag` ('ul' | 'ol'). If already inside a list of the other type,
// converts it instead of nesting.
export function toggleList(root: HTMLElement, listTag: 'ul' | 'ol'): void {
  const range = getRange();
  if (!range) return;

  const existingLi = findAncestor(root, range.commonAncestorContainer, ['li']);

  if (existingLi) {
    const list = existingLi.parentElement;
    if (list && list.tagName.toLowerCase() === listTag) {
      unwrapListItem(root, existingLi, list as HTMLElement);
    } else if (list) {
      // Convert ul <-> ol by renaming the list element.
      const replacement = document.createElement(listTag);
      while (list.firstChild) replacement.appendChild(list.firstChild);
      list.parentNode?.replaceChild(replacement, list);
    }
    return;
  }

  const block = findBlock(root, range.commonAncestorContainer);
  if (!block) return;

  const list = document.createElement(listTag);
  const li = document.createElement('li');
  while (block.firstChild) li.appendChild(block.firstChild);
  list.appendChild(li);
  block.parentNode?.replaceChild(list, block);

  setCaretAt(li, li.childNodes.length);
}

function unwrapListItem(root: HTMLElement, li: HTMLElement, list: HTMLElement): void {
  const p = document.createElement('p');
  while (li.firstChild) p.appendChild(li.firstChild);

  const isOnlyItem = list.children.length === 1;
  if (isOnlyItem) {
    list.parentNode?.replaceChild(p, list);
  } else {
    list.parentNode?.insertBefore(p, list.nextSibling);
    li.remove();
  }

  setCaretAt(p, p.childNodes.length);
}

export function isListActive(root: HTMLElement, listTag: 'ul' | 'ol'): boolean {
  const range = getRange();
  if (!range) return false;
  const li = findAncestor(root, range.commonAncestorContainer, ['li']);
  if (!li) return false;
  return li.parentElement?.tagName.toLowerCase() === listTag;
}

// Nests the current <li> one level deeper by moving it into a new sub-list
// inside the previous sibling <li> (standard Tab-to-indent behavior). Does
// nothing if there's no preceding sibling to nest under.
export function indentListItem(root: HTMLElement): boolean {
  const range = getRange();
  if (!range) return false;
  const li = findAncestor(root, range.commonAncestorContainer, ['li']);
  if (!li) return false;

  const prevLi = li.previousElementSibling;
  if (!prevLi || prevLi.tagName.toLowerCase() !== 'li') return false;

  const parentList = li.parentElement!;
  const listTag = parentList.tagName.toLowerCase();

  let subList = prevLi.querySelector(`:scope > ${listTag}`) as HTMLElement | null;
  if (!subList) {
    subList = document.createElement(listTag);
    prevLi.appendChild(subList);
  }

  subList.appendChild(li);
  return true;
}

// Un-nests the current <li> one level (Shift+Tab), moving it up to become
// a sibling of its parent <li>. Does nothing if already at the top level.
export function outdentListItem(root: HTMLElement): boolean {
  const range = getRange();
  if (!range) return false;
  const li = findAncestor(root, range.commonAncestorContainer, ['li']);
  if (!li) return false;

  const parentList = li.parentElement;
  if (!parentList) return false;
  const grandparentLi = parentList.parentElement;
  if (!grandparentLi || grandparentLi.tagName.toLowerCase() !== 'li') return false;

  const outerList = grandparentLi.parentElement;
  if (!outerList) return false;

  outerList.insertBefore(li, grandparentLi.nextSibling);

  if (parentList.children.length === 0) {
    parentList.remove();
  }

  return true;
}

// Handles Enter inside a list: pressing Enter on an empty <li> exits the
// list (converts that item to a paragraph after the list) instead of
// creating another empty item. Returns true if it handled the event
// (caller should preventDefault), false to let the browser's default
// contentEditable behavior run.
export function handleListEnter(root: HTMLElement): boolean {
  const range = getRange();
  if (!range || !range.collapsed) return false;
  const li = findAncestor(root, range.commonAncestorContainer, ['li']);
  if (!li) return false;
  if (li.textContent?.trim() !== '') return false;

  const list = li.parentElement;
  if (!list) return false;

  const p = document.createElement('p');
  p.innerHTML = '<br>';

  if (li.nextElementSibling) {
    // Splitting a list in the middle isn't needed for an empty final item;
    // for an empty non-last item, just drop the empty item and insert the
    // paragraph before the remainder — matches common editor behavior of
    // "empty item + Enter exits the list at that point".
    list.parentNode?.insertBefore(p, list);
  } else {
    list.parentNode?.insertBefore(p, list.nextSibling);
  }

  li.remove();
  if (list.children.length === 0) list.remove();

  setCaretAt(p, 0);
  return true;
}

// Handles Backspace at the very start of a list item: exits the list
// (converts the item to a paragraph) rather than merging into the
// previous item's text, when the item is the first in its list.
export function handleListBackspace(root: HTMLElement): boolean {
  const range = getRange();
  if (!range || !range.collapsed || range.startOffset !== 0) return false;

  const li = findAncestor(root, range.commonAncestorContainer, ['li']);
  if (!li) return false;
  if (li.previousElementSibling) return false;

  // Only handle when caret is truly at the start of the <li>'s content.
  const list = li.parentElement;
  if (!list) return false;

  const p = document.createElement('p');
  while (li.firstChild) p.appendChild(li.firstChild);
  if (!p.firstChild) p.innerHTML = '<br>';

  list.parentNode?.insertBefore(p, list);
  li.remove();
  if (list.children.length === 0) list.remove();

  setCaretAt(p, 0);
  return true;
}
