function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

const ANCHOR_ID_PATTERN = /^[A-Za-z][\w-]*$/;

export function isValidAnchorName(name: string): boolean {
  return ANCHOR_ID_PATTERN.test(name);
}

// Inserts a zero-width named anchor at the caret: <a id="name"></a>.
// Returns false if the name is empty/invalid or already used in the doc.
export function insertAnchor(root: HTMLElement, name: string): boolean {
  if (!isValidAnchorName(name)) return false;
  // Safe to interpolate directly: isValidAnchorName already restricted
  // `name` to [A-Za-z][\w-]*, which contains no CSS-selector metacharacters.
  if (root.querySelector(`#${name}`)) return false;

  const range = getRange();
  if (!range) return false;

  const anchor = document.createElement('a');
  anchor.id = name;
  anchor.className = 'omar-text-editor-anchor';

  const collapsed = range.cloneRange();
  collapsed.collapse(true);
  collapsed.insertNode(anchor);

  const caretRange = document.createRange();
  caretRange.setStartAfter(anchor);
  caretRange.collapse(true);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(caretRange);

  return true;
}

export function removeAnchor(root: HTMLElement, name: string): boolean {
  if (!isValidAnchorName(name)) return false;
  const el = root.querySelector(`#${name}.omar-text-editor-anchor`);
  if (!el) return false;
  el.remove();
  return true;
}

// Finds the anchor element the caret is currently inside/adjacent to, so
// the dialog can reopen pre-filled with its name (edit) or a context menu
// can offer to remove it — mirroring getSelectedImage's lookup shape.
export function getSelectedAnchor(root: HTMLElement): HTMLElement | null {
  const findAnchor = (node: Node | null): HTMLElement | null => {
    let current: Node | null = node;
    while (current && current !== root.parentNode) {
      if (
        current.nodeType === Node.ELEMENT_NODE &&
        (current as Element).classList.contains('omar-text-editor-anchor')
      ) {
        return current as HTMLElement;
      }
      current = current.parentNode;
    }
    return null;
  };

  const range = getRange();
  if (range) {
    const fromRange = findAnchor(range.startContainer);
    if (fromRange) return fromRange;
    const node = range.startContainer.nodeType === Node.ELEMENT_NODE
      ? range.startContainer.childNodes[range.startOffset]
      : null;
    if (node) {
      const fromChild = findAnchor(node);
      if (fromChild) return fromChild;
    }
  }

  const selection = window.getSelection();
  return findAnchor(selection?.anchorNode ?? null);
}

export function renameAnchor(root: HTMLElement, anchor: HTMLElement, name: string): boolean {
  if (!isValidAnchorName(name)) return false;
  const existing = root.querySelector(`#${name}`);
  if (existing && existing !== anchor) return false;
  anchor.id = name;
  return true;
}
