import { isSafeUrl } from './Schema';

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestorLink(root: HTMLElement, node: Node): HTMLAnchorElement | null {
  let current: Node | null = node;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE && (current as Element).tagName === 'A') {
      return current as HTMLAnchorElement;
    }
    current = current.parentNode;
  }
  return null;
}

export interface LinkAttrs {
  href: string;
  text?: string;
  title?: string;
  newTab?: boolean;
}

// Inserts a new link (using LinkAttrs.text, or the current selection's text
// if not given) or updates the link the caret is currently inside. Returns
// false (and makes no change) if href is unsafe or empty.
export function insertOrUpdateLink(root: HTMLElement, attrs: LinkAttrs): boolean {
  if (!attrs.href || !isSafeUrl(attrs.href)) return false;

  const range = getRange();
  if (!range) return false;

  const existing = findAncestorLink(root, range.commonAncestorContainer);

  if (existing) {
    applyAttrs(existing, attrs);
    return true;
  }

  const a = document.createElement('a');
  applyAttrs(a, attrs);

  if (range.collapsed) {
    a.textContent = attrs.text || attrs.href;
    range.insertNode(a);
  } else if (attrs.text) {
    range.deleteContents();
    a.textContent = attrs.text;
    range.insertNode(a);
  } else {
    try {
      range.surroundContents(a);
    } catch {
      const fragment = range.extractContents();
      a.appendChild(fragment);
      range.insertNode(a);
    }
  }

  const newRange = document.createRange();
  newRange.selectNodeContents(a);
  newRange.collapse(false);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);

  return true;
}

function applyAttrs(a: HTMLAnchorElement, attrs: LinkAttrs): void {
  a.setAttribute('href', attrs.href);
  if (attrs.title) a.setAttribute('title', attrs.title);
  else a.removeAttribute('title');

  if (attrs.newTab) {
    a.setAttribute('target', '_blank');
    a.setAttribute('rel', 'noopener noreferrer');
  } else {
    a.removeAttribute('target');
    a.removeAttribute('rel');
  }
}

export function removeLink(root: HTMLElement): boolean {
  const range = getRange();
  if (!range) return false;

  const link = findAncestorLink(root, range.commonAncestorContainer);
  if (!link) return false;

  const parent = link.parentNode;
  if (!parent) return false;

  while (link.firstChild) parent.insertBefore(link.firstChild, link);
  parent.removeChild(link);
  return true;
}

export function getCurrentLink(root: HTMLElement): HTMLAnchorElement | null {
  const range = getRange();
  if (!range) return null;
  return findAncestorLink(root, range.commonAncestorContainer);
}

export function isLinkActive(root: HTMLElement): boolean {
  return getCurrentLink(root) !== null;
}
