// Original table engine: insertion, row/column/cell structural edits,
// header toggling, and cell navigation.

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestor(node: Node, tags: string[]): HTMLElement | null {
  let current: Node | null = node;
  while (current) {
    if (current.nodeType === Node.ELEMENT_NODE && tags.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

function setCaretAt(node: Node, offset: number): void {
  const range = document.createRange();
  range.setStart(node, offset);
  range.setEnd(node, offset);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

export function insertTable(root: HTMLElement, rows: number, cols: number, withHeader = false): void {
  const table = document.createElement('table');
  const tbody = document.createElement('tbody');

  for (let r = 0; r < rows; r++) {
    const tr = document.createElement('tr');
    for (let c = 0; c < cols; c++) {
      const useHeader = withHeader && r === 0;
      const cell = document.createElement(useHeader ? 'th' : 'td');
      cell.innerHTML = '<br>';
      tr.appendChild(cell);
    }
    tbody.appendChild(tr);
  }
  table.appendChild(tbody);

  const range = getRange();
  if (range) {
    range.deleteContents();
    range.insertNode(table);
  } else {
    root.appendChild(table);
  }

  const p = document.createElement('p');
  p.innerHTML = '<br>';
  table.parentNode?.insertBefore(p, table.nextSibling);

  const firstCell = table.querySelector('td, th');
  if (firstCell) setCaretAt(firstCell, 0);
}

export function getCurrentCell(node: Node): HTMLTableCellElement | null {
  return findAncestor(node, ['td', 'th']) as HTMLTableCellElement | null;
}

export function getCurrentTable(node: Node): HTMLTableElement | null {
  return findAncestor(node, ['table']) as HTMLTableElement | null;
}

function getCellIndex(cell: HTMLTableCellElement): number {
  return Array.prototype.indexOf.call(cell.parentElement!.children, cell);
}

export function insertRow(table: HTMLTableElement, afterRow: HTMLTableRowElement, before = false): void {
  const cols = afterRow.children.length;
  const newRow = document.createElement('tr');
  for (let i = 0; i < cols; i++) {
    const cell = document.createElement('td');
    cell.innerHTML = '<br>';
    newRow.appendChild(cell);
  }
  afterRow.parentNode?.insertBefore(newRow, before ? afterRow : afterRow.nextSibling);
}

export function deleteRow(row: HTMLTableRowElement): void {
  const table = findAncestor(row, ['table']) as HTMLTableElement | null;
  const tbody = row.parentElement;
  row.remove();
  if (table && tbody && tbody.children.length === 0) {
    table.remove();
  }
}

export function insertColumn(table: HTMLTableElement, atIndex: number, before = false): void {
  const rows = table.querySelectorAll('tr');
  rows.forEach((row) => {
    const referenceCell = row.children[atIndex] as HTMLTableCellElement | undefined;
    const cell = document.createElement(referenceCell?.tagName.toLowerCase() === 'th' ? 'th' : 'td');
    cell.innerHTML = '<br>';
    if (referenceCell) {
      row.insertBefore(cell, before ? referenceCell : referenceCell.nextSibling);
    } else {
      row.appendChild(cell);
    }
  });
}

export function deleteColumn(table: HTMLTableElement, atIndex: number): void {
  const rows = table.querySelectorAll('tr');
  rows.forEach((row) => {
    row.children[atIndex]?.remove();
  });
  if (table.querySelector('tr')?.children.length === 0) {
    table.remove();
  }
}

export function deleteTable(table: HTMLTableElement): void {
  table.remove();
}

// Merges `cell` with the cell to its right in the same row, combining
// content and increasing colspan. Returns false if there's no cell to merge
// with (already at the row's last column).
export function mergeCellRight(cell: HTMLTableCellElement): boolean {
  const next = cell.nextElementSibling as HTMLTableCellElement | null;
  if (!next || (next.tagName !== 'TD' && next.tagName !== 'TH')) return false;

  while (next.firstChild) cell.appendChild(next.firstChild);
  const currentSpan = parseInt(cell.getAttribute('colspan') || '1', 10);
  const nextSpan = parseInt(next.getAttribute('colspan') || '1', 10);
  cell.setAttribute('colspan', String(currentSpan + nextSpan));
  next.remove();
  return true;
}

// Splits a merged cell (colspan > 1) back into individual cells.
export function splitCell(cell: HTMLTableCellElement): boolean {
  const span = parseInt(cell.getAttribute('colspan') || '1', 10);
  if (span <= 1) return false;

  cell.removeAttribute('colspan');
  for (let i = 1; i < span; i++) {
    const newCell = document.createElement(cell.tagName.toLowerCase());
    newCell.innerHTML = '<br>';
    cell.parentNode?.insertBefore(newCell, cell.nextSibling);
  }
  return true;
}

export function toggleHeaderRow(table: HTMLTableElement): void {
  const firstRow = table.querySelector('tr');
  if (!firstRow) return;

  const isHeader = firstRow.children[0]?.tagName === 'TH';
  const newTag = isHeader ? 'td' : 'th';

  Array.from(firstRow.children).forEach((cell) => {
    const replacement = document.createElement(newTag);
    replacement.innerHTML = cell.innerHTML;
    for (const attr of Array.from(cell.attributes)) {
      replacement.setAttribute(attr.name, attr.value);
    }
    cell.parentNode?.replaceChild(replacement, cell);
  });
}

// Moves the caret to the next cell (Tab) or previous cell (Shift+Tab).
// Tab from the last cell of the last row creates a new row and moves into
// its first cell. Returns true if handled.
export function navigateCell(table: HTMLTableElement, cell: HTMLTableCellElement, forward: boolean): boolean {
  const allCells = Array.from(table.querySelectorAll('td, th')) as HTMLTableCellElement[];
  const currentIndex = allCells.indexOf(cell);
  if (currentIndex === -1) return false;

  if (forward && currentIndex === allCells.length - 1) {
    const lastRow = table.querySelector('tr:last-child') as HTMLTableRowElement;
    insertRow(table, lastRow, false);
    const newFirstCell = table.querySelector('tr:last-child td, tr:last-child th');
    if (newFirstCell) setCaretAt(newFirstCell, 0);
    return true;
  }

  const targetIndex = forward ? currentIndex + 1 : currentIndex - 1;
  const target = allCells[targetIndex];
  if (!target) return false;

  setCaretAt(target, 0);
  return true;
}

export const COLUMN_RESIZE_MIN_PX = 30;

export function resizeColumn(table: HTMLTableElement, colIndex: number, widthPx: number): void {
  const clamped = Math.max(COLUMN_RESIZE_MIN_PX, widthPx);
  const rows = table.querySelectorAll('tr');
  rows.forEach((row) => {
    const cell = row.children[colIndex] as HTMLTableCellElement | undefined;
    if (cell) cell.style.width = `${clamped}px`;
  });
}

const ROW_RESIZE_MIN_PX = 20;

// Row height is set on the <tr> itself rather than on each cell: standard
// table layout already respects a row's height from its <tr>, and setting
// it there (vs. per-cell) avoids fighting rowspan'd cells that belong to
// other rows.
export function resizeRow(table: HTMLTableElement, rowIndex: number, heightPx: number): void {
  const clamped = Math.max(ROW_RESIZE_MIN_PX, heightPx);
  const row = table.querySelectorAll('tr')[rowIndex] as HTMLTableRowElement | undefined;
  if (row) row.style.height = `${clamped}px`;
}

export interface CellPosition {
  row: number;
  col: number;
}

// Row/column index of `cell` accounting for colspan/rowspan of cells that
// precede it, so indices line up across rows with merged cells. Needed by
// range selection (getCellRange) to find the true bounding rectangle rather
// than raw DOM child indices, which skip over spanned-away positions.
export function getCellPosition(table: HTMLTableElement, cell: HTMLTableCellElement): CellPosition | null {
  const rows = Array.from(table.querySelectorAll('tr'));
  // occupied[r][c] = true once a cell (or its span) has claimed that slot.
  const occupied: boolean[][] = [];

  for (let r = 0; r < rows.length; r++) {
    occupied[r] = occupied[r] || [];
    const cellsInRow = Array.from(rows[r]!.children) as HTMLTableCellElement[];
    let c = 0;
    for (const rowCell of cellsInRow) {
      while (occupied[r]![c]) c++;

      const rowspan = parseInt(rowCell.getAttribute('rowspan') || '1', 10);
      const colspan = parseInt(rowCell.getAttribute('colspan') || '1', 10);
      for (let dr = 0; dr < rowspan; dr++) {
        occupied[r + dr] = occupied[r + dr] || [];
        for (let dc = 0; dc < colspan; dc++) {
          occupied[r + dr]![c + dc] = true;
        }
      }

      if (rowCell === cell) return { row: r, col: c };
      c += colspan;
    }
  }
  return null;
}

// All cells (in document order) whose top-left position falls within the
// rectangular bounding box of the two given cells' positions.
export function getCellRange(
  table: HTMLTableElement,
  cellA: HTMLTableCellElement,
  cellB: HTMLTableCellElement,
): HTMLTableCellElement[] {
  const posA = getCellPosition(table, cellA);
  const posB = getCellPosition(table, cellB);
  if (!posA || !posB) return [];

  const minRow = Math.min(posA.row, posB.row);
  const maxRow = Math.max(posA.row, posB.row);
  const minCol = Math.min(posA.col, posB.col);
  const maxCol = Math.max(posA.col, posB.col);

  const result: HTMLTableCellElement[] = [];
  const rows = table.querySelectorAll('tr');
  rows.forEach((row) => {
    Array.from(row.children).forEach((child) => {
      const cell = child as HTMLTableCellElement;
      const pos = getCellPosition(table, cell);
      if (pos && pos.row >= minRow && pos.row <= maxRow && pos.col >= minCol && pos.col <= maxCol) {
        result.push(cell);
      }
    });
  });
  return result;
}

// Merges every cell in `cells` into the top-left one: concatenates their
// content in row-major order and sets the surviving cell's colspan/rowspan
// to cover the full rectangle those cells occupied. Returns the surviving
// cell, or null if `cells` is empty.
export function mergeCellRange(table: HTMLTableElement, cells: HTMLTableCellElement[]): HTMLTableCellElement | null {
  if (cells.length === 0) return null;
  if (cells.length === 1) return cells[0]!;

  const positioned = cells
    .map((cell) => ({ cell, pos: getCellPosition(table, cell)! }))
    .filter((entry) => entry.pos)
    .sort((a, b) => (a.pos.row - b.pos.row) || (a.pos.col - b.pos.col));

  const minRow = Math.min(...positioned.map((p) => p.pos.row));
  const maxRow = Math.max(...positioned.map((p) => p.pos.row));
  const minCol = Math.min(...positioned.map((p) => p.pos.col));
  const maxCol = Math.max(...positioned.map((p) => p.pos.col));

  const target = positioned[0]!.cell;

  for (const { cell } of positioned) {
    if (cell === target) continue;
    while (cell.firstChild) target.appendChild(cell.firstChild);
    cell.remove();
  }

  const rowSpan = maxRow - minRow + 1;
  const colSpan = maxCol - minCol + 1;
  if (rowSpan > 1) target.setAttribute('rowspan', String(rowSpan));
  else target.removeAttribute('rowspan');
  if (colSpan > 1) target.setAttribute('colspan', String(colSpan));
  else target.removeAttribute('colspan');

  if (!target.firstChild) target.innerHTML = '<br>';
  return target;
}

// Deletes every row that contains at least one of the given cells.
export function deleteRows(table: HTMLTableElement, cells: HTMLTableCellElement[]): void {
  const rows = new Set<HTMLTableRowElement>();
  cells.forEach((cell) => {
    const row = cell.parentElement as HTMLTableRowElement | null;
    if (row) rows.add(row);
  });
  rows.forEach((row) => deleteRow(row));
}

// Deletes every column index touched by the given cells, accounting for
// merged cells the same way getCellPosition does. Indices are deleted
// high-to-low so earlier deletions don't shift later target indices.
export function deleteColumns(table: HTMLTableElement, cells: HTMLTableCellElement[]): void {
  const cols = new Set<number>();
  cells.forEach((cell) => {
    const pos = getCellPosition(table, cell);
    if (pos) cols.add(pos.col);
  });
  Array.from(cols)
    .sort((a, b) => b - a)
    .forEach((colIndex) => deleteColumn(table, colIndex));
}
