export interface DialogField {
  name: string;
  label: string;
  // 'note' renders `label` as plain non-interactive help text (no input,
  // never collected into onSubmit's values) — for inline usage guidance
  // that doesn't fit a field's own label, e.g. the media dialog explaining
  // what kinds of URL are accepted.
  type: 'text' | 'checkbox' | 'select' | 'textarea' | 'note';
  defaultValue?: string | boolean;
  options?: { label: string; value: string }[]; // for type: 'select'
}

export interface DialogConfig {
  title: string;
  fields: DialogField[];
  onSubmit: (values: Record<string, string | boolean>) => void;
  onCancel?: () => void;
  submitLabel?: string;
}

// A minimal modal dialog framework: renders a form from field defs, traps
// focus while open, closes on Esc or backdrop click, and passes collected
// values to onSubmit. Reused by link/image/table/charmap dialogs in later
// phases.
export class Dialog {
  private overlayEl: HTMLElement;
  private dialogEl: HTMLElement;
  private inputs = new Map<string, HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>();
  private previouslyFocused: Element | null;

  constructor(private config: DialogConfig) {
    this.previouslyFocused = document.activeElement;

    this.overlayEl = document.createElement('div');
    this.overlayEl.className = 'omar-text-editor-dialog-overlay';

    this.dialogEl = document.createElement('div');
    this.dialogEl.className = 'omar-text-editor-dialog';
    this.dialogEl.setAttribute('role', 'dialog');
    this.dialogEl.setAttribute('aria-modal', 'true');

    this.render();
    this.overlayEl.appendChild(this.dialogEl);
    document.body.appendChild(this.overlayEl);

    this.overlayEl.addEventListener('mousedown', (e) => {
      if (e.target === this.overlayEl) this.cancel();
    });
    document.addEventListener('keydown', this.handleKeydown);

    this.focusFirstField();
  }

  private render(): void {
    const header = document.createElement('div');
    header.className = 'omar-text-editor-dialog-header';
    header.textContent = this.config.title;
    this.dialogEl.appendChild(header);

    const form = document.createElement('form');
    form.className = 'omar-text-editor-dialog-body';
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      this.submit();
    });

    for (const field of this.config.fields) {
      form.appendChild(this.renderField(field));
    }

    const footer = document.createElement('div');
    footer.className = 'omar-text-editor-dialog-footer';

    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.addEventListener('click', () => this.cancel());

    const submitBtn = document.createElement('button');
    submitBtn.type = 'submit';
    submitBtn.className = 'omar-text-editor-dialog-primary';
    submitBtn.textContent = this.config.submitLabel ?? 'OK';

    footer.appendChild(cancelBtn);
    footer.appendChild(submitBtn);
    form.appendChild(footer);

    this.dialogEl.appendChild(form);
  }

  private renderField(field: DialogField): HTMLElement {
    if (field.type === 'note') {
      const note = document.createElement('p');
      note.className = 'omar-text-editor-dialog-note';
      note.textContent = field.label;
      return note;
    }

    const wrapper = document.createElement('label');
    wrapper.className = 'omar-text-editor-dialog-field';

    const labelText = document.createElement('span');
    labelText.textContent = field.label;
    wrapper.appendChild(labelText);

    let input: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;

    if (field.type === 'select') {
      input = document.createElement('select');
      for (const opt of field.options ?? []) {
        const optionEl = document.createElement('option');
        optionEl.value = opt.value;
        optionEl.textContent = opt.label;
        input.appendChild(optionEl);
      }
      if (typeof field.defaultValue === 'string') input.value = field.defaultValue;
    } else if (field.type === 'textarea') {
      input = document.createElement('textarea');
      if (typeof field.defaultValue === 'string') input.value = field.defaultValue;
    } else {
      input = document.createElement('input');
      input.type = field.type === 'checkbox' ? 'checkbox' : 'text';
      if (field.type === 'checkbox') {
        (input as HTMLInputElement).checked = !!field.defaultValue;
      } else if (typeof field.defaultValue === 'string') {
        input.value = field.defaultValue;
      }
    }

    input.name = field.name;
    this.inputs.set(field.name, input);
    wrapper.appendChild(input);
    return wrapper;
  }

  private focusFirstField(): void {
    const first = this.inputs.values().next().value;
    first?.focus();
  }

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      e.preventDefault();
      this.cancel();
      return;
    }
    if (e.key === 'Tab') {
      this.trapFocus(e);
    }
  };

  private trapFocus(e: KeyboardEvent): void {
    const focusable = Array.from(
      this.dialogEl.querySelectorAll<HTMLElement>('input, select, textarea, button'),
    );
    if (focusable.length === 0) return;

    const first = focusable[0]!;
    const last = focusable[focusable.length - 1]!;

    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  private collectValues(): Record<string, string | boolean> {
    const values: Record<string, string | boolean> = {};
    for (const [name, input] of this.inputs) {
      values[name] = input instanceof HTMLInputElement && input.type === 'checkbox'
        ? input.checked
        : input.value;
    }
    return values;
  }

  private submit(): void {
    const values = this.collectValues();
    this.close();
    this.config.onSubmit(values);
  }

  private cancel(): void {
    this.close();
    this.config.onCancel?.();
  }

  private close(): void {
    document.removeEventListener('keydown', this.handleKeydown);
    this.overlayEl.remove();
    if (this.previouslyFocused instanceof HTMLElement) {
      this.previouslyFocused.focus();
    }
  }
}

export interface PickerDialogConfig {
  title: string;
  searchPlaceholder?: string;
  onClose?: () => void;
}

// Shares the Dialog framework's modal shell (overlay, header, focus trap,
// Esc/backdrop-to-close) but replaces the field-based form body with an
// arbitrary caller-rendered body — used by pickers like emoticons/charmap
// where the content is a searchable grid of clickable items rather than a
// set of form fields to submit.
export class PickerDialog {
  readonly bodyEl: HTMLElement;
  readonly searchInput: HTMLInputElement | null = null;

  private overlayEl: HTMLElement;
  private dialogEl: HTMLElement;
  private previouslyFocused: Element | null;

  constructor(private config: PickerDialogConfig) {
    this.previouslyFocused = document.activeElement;

    this.overlayEl = document.createElement('div');
    this.overlayEl.className = 'omar-text-editor-dialog-overlay';

    this.dialogEl = document.createElement('div');
    this.dialogEl.className = 'omar-text-editor-dialog omar-text-editor-picker-dialog';
    this.dialogEl.setAttribute('role', 'dialog');
    this.dialogEl.setAttribute('aria-modal', 'true');

    const header = document.createElement('div');
    header.className = 'omar-text-editor-dialog-header';
    header.textContent = config.title;
    this.dialogEl.appendChild(header);

    if (config.searchPlaceholder !== undefined) {
      this.searchInput = document.createElement('input');
      this.searchInput.type = 'text';
      this.searchInput.className = 'omar-text-editor-picker-search';
      this.searchInput.placeholder = config.searchPlaceholder;
      this.dialogEl.appendChild(this.searchInput);
    }

    this.bodyEl = document.createElement('div');
    this.bodyEl.className = 'omar-text-editor-picker-body';
    this.dialogEl.appendChild(this.bodyEl);

    this.overlayEl.appendChild(this.dialogEl);
    document.body.appendChild(this.overlayEl);

    this.overlayEl.addEventListener('mousedown', (e) => {
      if (e.target === this.overlayEl) this.close();
    });
    document.addEventListener('keydown', this.handleKeydown);

    (this.searchInput ?? this.dialogEl).focus();
  }

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      e.preventDefault();
      this.close();
    }
  };

  close(): void {
    document.removeEventListener('keydown', this.handleKeydown);
    this.overlayEl.remove();
    if (this.previouslyFocused instanceof HTMLElement) {
      this.previouslyFocused.focus();
    }
    this.config.onClose?.();
  }
}
