export interface ColorPickerOptions {
  onPick: (color: string) => void;
  onClear?: () => void;
}

// A palette of common colors, spanning grayscale plus a handful of common
// hues at a couple of lightness steps — enough range for typical rich-text
// use without turning into a full color-theory picker.
const PALETTE = [
  '#000000', '#424242', '#636363', '#9c9c9c', '#cccccc', '#efefef', '#f7f7f7', '#ffffff',
  '#c0392b', '#e74c3c', '#e67e22', '#f1c40f', '#2ecc71', '#1abc9c', '#3498db', '#9b59b6',
  '#7f1d1d', '#991b1b', '#9a3412', '#854d0e', '#166534', '#115e59', '#1e3a8a', '#581c87',
];

// A small anchored popover for picking a color: a swatch grid of common
// colors, a native color input for anything else, and (when onClear is
// given) a "Remove color" action — reused by the text/background color
// toolbar buttons.
export class ColorPicker {
  private el: HTMLElement;

  constructor(anchor: HTMLElement, options: ColorPickerOptions) {
    this.el = document.createElement('div');
    this.el.className = 'omar-text-editor-color-picker';

    const grid = document.createElement('div');
    grid.className = 'omar-text-editor-color-picker-grid';
    for (const color of PALETTE) {
      const swatch = document.createElement('button');
      swatch.type = 'button';
      swatch.className = 'omar-text-editor-color-picker-swatch';
      swatch.style.backgroundColor = color;
      swatch.title = color;
      swatch.addEventListener('mousedown', (e) => e.preventDefault()); // keep editor selection
      swatch.addEventListener('click', () => {
        options.onPick(color);
        this.close();
      });
      grid.appendChild(swatch);
    }
    this.el.appendChild(grid);

    const customRow = document.createElement('label');
    customRow.className = 'omar-text-editor-color-picker-custom';
    const customInput = document.createElement('input');
    customInput.type = 'color';
    customInput.addEventListener('input', () => {
      options.onPick(customInput.value);
    });
    customInput.addEventListener('change', () => this.close());
    customRow.appendChild(customInput);
    customRow.appendChild(document.createTextNode('Custom…'));
    this.el.appendChild(customRow);

    if (options.onClear) {
      const clearBtn = document.createElement('button');
      clearBtn.type = 'button';
      clearBtn.className = 'omar-text-editor-color-picker-clear';
      clearBtn.textContent = 'Remove color';
      clearBtn.addEventListener('mousedown', (e) => e.preventDefault());
      clearBtn.addEventListener('click', () => {
        options.onClear?.();
        this.close();
      });
      this.el.appendChild(clearBtn);
    }

    document.body.appendChild(this.el);

    const rect = anchor.getBoundingClientRect();
    this.el.style.left = `${rect.left}px`;
    this.el.style.top = `${rect.bottom + 4}px`;

    document.addEventListener('mousedown', this.handleOutsideClick);
    document.addEventListener('keydown', this.handleKeydown);
  }

  private handleOutsideClick = (e: MouseEvent): void => {
    if (!this.el.contains(e.target as Node)) this.close();
  };

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') this.close();
  };

  close(): void {
    document.removeEventListener('mousedown', this.handleOutsideClick);
    document.removeEventListener('keydown', this.handleKeydown);
    this.el.remove();
  }
}
