// Text search across the editable area's text nodes, with highlighting via
// temporary <mark> wrapper elements, next/prev navigation, and single or
// bulk replace. Operates on plain text content — matches never span
// element boundaries (e.g. across a bold/italic split), which mirrors how
// most rich text editors' find-and-replace behaves.

export interface SearchOptions {
  matchCase?: boolean;
  wholeWord?: boolean;
}

export interface SearchMatch {
  node: Text;
  start: number;
  end: number;
}

function buildPattern(query: string, options: SearchOptions): RegExp | null {
  if (!query) return null;
  const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = options.wholeWord ? `\\b${escaped}\\b` : escaped;
  return new RegExp(pattern, options.matchCase ? 'g' : 'gi');
}

export function findAllMatches(root: HTMLElement, query: string, options: SearchOptions = {}): SearchMatch[] {
  const regex = buildPattern(query, options);
  if (!regex) return [];

  const matches: SearchMatch[] = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode() as Text | null;

  while (node) {
    const text = node.data;
    let match: RegExpExecArray | null;
    regex.lastIndex = 0;
    while ((match = regex.exec(text)) !== null) {
      matches.push({ node, start: match.index, end: match.index + match[0].length });
      if (match[0].length === 0) regex.lastIndex++; // avoid infinite loop on empty matches
    }
    node = walker.nextNode() as Text | null;
  }

  return matches;
}

const HIGHLIGHT_CLASS = 'omar-text-editor-search-highlight';
const ACTIVE_CLASS = 'omar-text-editor-search-highlight-active';

// Wraps every match in a <mark> so it's visible, and returns the list of
// mark elements in document order (index-aligned with the matches that
// were passed in, since each match becomes exactly one mark).
export function highlightMatches(matches: SearchMatch[]): HTMLElement[] {
  // Process in reverse document order per node so earlier splits don't
  // invalidate later matches' offsets within the same text node.
  const byNode = new Map<Text, SearchMatch[]>();
  for (const m of matches) {
    if (!byNode.has(m.node)) byNode.set(m.node, []);
    byNode.get(m.node)!.push(m);
  }

  const marksByMatch = new Map<SearchMatch, HTMLElement>();

  for (const [node, nodeMatches] of byNode) {
    const sorted = [...nodeMatches].sort((a, b) => b.start - a.start);
    for (const m of sorted) {
      const range = document.createRange();
      range.setStart(m.node, m.start);
      range.setEnd(m.node, m.end);
      const mark = document.createElement('mark');
      mark.className = HIGHLIGHT_CLASS;
      range.surroundContents(mark);
      marksByMatch.set(m, mark);
    }
  }

  return matches.map((m) => marksByMatch.get(m)!);
}

export function clearHighlights(root: HTMLElement): void {
  const marks = root.querySelectorAll(`mark.${HIGHLIGHT_CLASS}`);
  marks.forEach((mark) => {
    const parent = mark.parentNode;
    if (!parent) return;
    while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
    parent.removeChild(mark);
    parent.normalize();
  });
}

export function setActiveHighlight(marks: HTMLElement[], index: number): void {
  marks.forEach((mark, i) => mark.classList.toggle(ACTIVE_CLASS, i === index));
  marks[index]?.scrollIntoView?.({ block: 'nearest' });
}

export function replaceMatchAt(mark: HTMLElement, replacement: string): void {
  const textNode = document.createTextNode(replacement);
  mark.parentNode?.replaceChild(textNode, mark);
  textNode.parentElement?.normalize();
}

export function replaceAll(root: HTMLElement, query: string, replacement: string, options: SearchOptions = {}): number {
  const matches = findAllMatches(root, query, options);
  const marks = highlightMatches(matches);
  marks.forEach((mark) => replaceMatchAt(mark, replacement));
  return matches.length;
}
