export type NotificationType = 'info' | 'success' | 'error';

export interface NotificationOptions {
  message: string;
  type?: NotificationType;
  durationMs?: number; // 0 = stays until manually closed
}

// A small toast/banner, e.g. for "Invalid URL" errors from dialogs.
// Multiple notifications stack in a single container appended to <body>.
export class Notification {
  private static container: HTMLElement | null = null;

  private el: HTMLElement;
  private timer: ReturnType<typeof setTimeout> | null = null;

  constructor(options: NotificationOptions) {
    const container = Notification.getContainer();

    this.el = document.createElement('div');
    this.el.className = `omar-text-editor-notification omar-text-editor-notification-${options.type ?? 'info'}`;
    this.el.textContent = options.message;
    this.el.setAttribute('role', 'status');

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'omar-text-editor-notification-close';
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', () => this.close());
    this.el.appendChild(closeBtn);

    container.appendChild(this.el);

    const duration = options.durationMs ?? 4000;
    if (duration > 0) {
      this.timer = setTimeout(() => this.close(), duration);
    }
  }

  private static getContainer(): HTMLElement {
    if (!Notification.container || !document.body.contains(Notification.container)) {
      Notification.container = document.createElement('div');
      Notification.container.className = 'omar-text-editor-notification-container';
      document.body.appendChild(Notification.container);
    }
    return Notification.container;
  }

  close(): void {
    if (this.timer) clearTimeout(this.timer);
    this.el.remove();
  }
}
