import type { Editor } from '../../core/Editor';
import { registerPlugin } from '../../core/Editor';
import { Dialog } from '../../ui/Dialog';
import { Notification } from '../../ui/Notification';
import { registerToolbarButton } from '../../ui/Toolbar';
import { ContextMenuItem } from '../../ui/ContextMenu';
import {
  insertMediaEmbed,
  getSelectedMediaEmbed,
  getMediaAttrs,
  updateMediaEmbed,
  removeMediaEmbed,
  setMediaAlign,
  setMediaFullWidth,
} from '../../core/Media';
import { bookmarkSelection, restoreSelection } from '../../core/Selection';

const MEDIA_WRAPPER_CLASSES = [
  'omar-text-editor-media-embed',
  'omar-text-editor-media-video',
  'omar-text-editor-media-audio',
];

export function openMediaDialog(editor: Editor, target?: HTMLElement): void {
  const root = editor.getEditableElement();
  const existing = target ?? getSelectedMediaEmbed(root);
  const current = existing ? getMediaAttrs(existing) : { url: '' };
  const bookmark = bookmarkSelection(root);

  new Dialog({
    title: existing ? 'Edit Media' : 'Insert Media',
    submitLabel: existing ? 'Update' : 'Insert',
    fields: [
      {
        name: 'url', label: 'Video URL', type: 'text', defaultValue: current.url,
      },
      {
        name: '_note',
        label:
          'YouTube: paste any watch/share/embed link (e.g. https://www.youtube.com/watch?v=... or https://youtu.be/...). ' +
          'Vimeo: paste the video page link (e.g. https://vimeo.com/123456789). ' +
          'Also supported: Google Maps embed links, CodePen pens, Google Slides/Docs/Sheets share links, and Spotify track/album/playlist links. ' +
          'Self-hosted / any other host: paste a direct link to the video or audio file itself ' +
          "(e.g. https://your-cdn.com/video.mp4 or .../track.mp3) - it plays with the browser's built-in player.",
        type: 'note',
      },
      {
        name: 'poster', label: 'Poster image URL (optional, self-hosted video only)', type: 'text',
        defaultValue: current.poster ?? '',
      },
      { name: 'width', label: 'Width (optional, e.g. 640)', type: 'text', defaultValue: current.width ?? '' },
      { name: 'height', label: 'Height (optional, e.g. 360)', type: 'text', defaultValue: current.height ?? '' },
    ],
    onSubmit: (values) => {
      root.focus();
      const attrs = {
        url: String(values.url ?? '').trim(),
        poster: String(values.poster ?? '').trim() || undefined,
        width: String(values.width ?? '').trim() || undefined,
        height: String(values.height ?? '').trim() || undefined,
      };

      const ok = existing
        ? updateMediaEmbed(existing, attrs)
        : (() => {
            if (bookmark) restoreSelection(root, bookmark);
            return insertMediaEmbed(root, attrs);
          })();

      if (!ok) {
        new Notification({
          message: 'Enter a link from a supported provider (YouTube, Vimeo, Google Maps/Slides/Docs/Sheets, Spotify, CodePen), or a direct video/audio URL (https://…).',
          type: 'error',
        });
        return;
      }

      editor.execCommand('__syncAfterExternalEdit');
    },
  });
}

function buildMenuItems(editor: Editor, wrapper: HTMLElement): ContextMenuItem[] {
  const commit = () => editor.execCommand('__syncAfterExternalEdit');

  return [
    { label: 'Edit media…', onSelect: () => openMediaDialog(editor, wrapper) },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Align left', onSelect: () => { setMediaAlign(wrapper, 'left'); commit(); } },
    { label: 'Align center', onSelect: () => { setMediaAlign(wrapper, 'center'); commit(); } },
    { label: 'Align right', onSelect: () => { setMediaAlign(wrapper, 'right'); commit(); } },
    { label: 'No alignment', onSelect: () => { setMediaAlign(wrapper, 'none'); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Full width', onSelect: () => { setMediaFullWidth(wrapper); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    {
      label: 'Remove media',
      onSelect: () => {
        removeMediaEmbed(wrapper);
        commit();
      },
    },
  ];
}

registerToolbarButton({ name: 'media', label: 'Insert media', icon: 'video', command: 'media' });

registerPlugin('media', (editor) => {
  editor.commands.register('media', () => openMediaDialog(editor));

  const resizer = editor.getMediaResizer();
  resizer.onResizeCommit(() => editor.execCommand('__syncAfterExternalEdit'));
  resizer.onMenuRequest((wrapper) => {
    if (!MEDIA_WRAPPER_CLASSES.some((cls) => wrapper.classList.contains(cls))) return null;
    return buildMenuItems(editor, wrapper);
  });
});
