import { isSafeUrl } from './Schema';

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

export interface ImageAttrs {
  src: string;
  alt?: string;
  width?: string;
  height?: string;
  align?: 'left' | 'center' | 'right' | 'none';
}

function applyAlign(img: HTMLImageElement, align: ImageAttrs['align']): void {
  img.style.removeProperty('float');
  img.style.removeProperty('display');
  img.style.removeProperty('margin-left');
  img.style.removeProperty('margin-right');

  if (align === 'left') {
    img.style.float = 'left';
    img.style.marginRight = '12px';
  } else if (align === 'right') {
    img.style.float = 'right';
    img.style.marginLeft = '12px';
  } else if (align === 'center') {
    img.style.display = 'block';
    img.style.marginLeft = 'auto';
    img.style.marginRight = 'auto';
  }
}

// Inserts a new <img> at the caret, or updates the currently-selected <img>
// if `existing` is passed (used by the resize/align dialog re-opening on an
// already-inserted image). Returns false for an unsafe/empty src.
export function insertOrUpdateImage(
  root: HTMLElement,
  attrs: ImageAttrs,
  existing?: HTMLImageElement | null,
): boolean {
  if (!attrs.src || !isSafeUrl(attrs.src)) return false;

  const img = existing ?? document.createElement('img');
  img.setAttribute('src', attrs.src);
  img.setAttribute('alt', attrs.alt ?? '');
  if (attrs.width) img.setAttribute('width', attrs.width);
  else img.removeAttribute('width');
  if (attrs.height) img.setAttribute('height', attrs.height);
  else img.removeAttribute('height');
  applyAlign(img, attrs.align);

  if (!existing) {
    const range = getRange();
    if (!range) {
      root.appendChild(img);
    } else {
      range.deleteContents();
      range.insertNode(img);
      range.setStartAfter(img);
      range.collapse(true);
      const sel = window.getSelection();
      sel?.removeAllRanges();
      sel?.addRange(range);
    }
  }

  return true;
}

export function setImageAlign(img: HTMLImageElement, align: ImageAttrs['align']): void {
  applyAlign(img, align);
}

export function getImageAlign(img: HTMLImageElement): NonNullable<ImageAttrs['align']> {
  if (img.style.float === 'left') return 'left';
  if (img.style.float === 'right') return 'right';
  if (img.style.display === 'block' && img.style.marginLeft === 'auto') return 'center';
  return 'none';
}

export function removeImage(img: HTMLImageElement): void {
  img.remove();
}

export function getSelectedImage(root: HTMLElement): HTMLImageElement | null {
  const range = getRange();
  if (range && range.startContainer.nodeType === Node.ELEMENT_NODE) {
    const node = range.startContainer.childNodes[range.startOffset];
    if (node instanceof HTMLImageElement) return node;
  }

  const selection = window.getSelection();
  const anchorNode = selection?.anchorNode;
  if (anchorNode instanceof HTMLImageElement && root.contains(anchorNode)) return anchorNode;

  return null;
}

// Reads a File (e.g. from drag-and-drop, paste, or a file <input>) as a
// data: URL. Omar Text Editor ships without a server, so embedding as base64 is the
// zero-config default; consumers who want server-side upload instead can
// intercept via an `imageUploadHandler` callback (registered by the caller,
// not here — this module stays a pure DOM/data utility).
export function readImageFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}
