export function getCurrentRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

export function setRange(range: Range): void {
  const sel = window.getSelection();
  if (!sel) return;
  sel.removeAllRanges();
  sel.addRange(range);
}

export function isSelectionInside(root: HTMLElement): boolean {
  const range = getCurrentRange();
  if (!range) return false;
  return root.contains(range.commonAncestorContainer);
}

// Walks up from the current selection to find the nearest ancestor element
// matching the predicate (e.g. an <a> tag, or a block with a given tag name),
// stopping at `root`.
export function closestAncestor(
  root: HTMLElement,
  predicate: (el: Element) => boolean,
): Element | null {
  const range = getCurrentRange();
  if (!range) return null;

  let node: Node | null = range.commonAncestorContainer;
  while (node && node !== root.parentNode) {
    if (node.nodeType === Node.ELEMENT_NODE && predicate(node as Element)) {
      return node as Element;
    }
    node = node.parentNode;
  }
  return null;
}

// A DOM-mutation-resistant bookmark: instead of holding a live Range/Node
// reference (which breaks once innerHTML is replaced, e.g. by undo/redo or
// setContent), we record the selection as child-index paths from `root`.
// As long as the tree shape at those paths is restored to something
// equivalent (same serialized HTML), the offsets remain valid.
export interface SelectionBookmark {
  startPath: number[];
  startOffset: number;
  endPath: number[];
  endOffset: number;
}

function pathTo(root: HTMLElement, node: Node): number[] {
  const path: number[] = [];
  let current: Node | null = node;
  while (current && current !== root) {
    const parent: Node | null = current.parentNode;
    if (!parent) break;
    path.unshift(Array.prototype.indexOf.call(parent.childNodes, current));
    current = parent;
  }
  return path;
}

function nodeAtPath(root: HTMLElement, path: number[]): Node | null {
  let current: Node = root;
  for (const index of path) {
    const child: ChildNode | undefined = current.childNodes[index];
    if (!child) return null;
    current = child;
  }
  return current;
}

export function bookmarkSelection(root: HTMLElement): SelectionBookmark | null {
  const range = getCurrentRange();
  if (!range || !root.contains(range.commonAncestorContainer)) return null;

  return {
    startPath: pathTo(root, range.startContainer),
    startOffset: range.startOffset,
    endPath: pathTo(root, range.endContainer),
    endOffset: range.endOffset,
  };
}

export function restoreSelection(root: HTMLElement, bookmark: SelectionBookmark): boolean {
  const startNode = nodeAtPath(root, bookmark.startPath);
  const endNode = nodeAtPath(root, bookmark.endPath);
  if (!startNode || !endNode) return false;

  const range = document.createRange();
  try {
    range.setStart(startNode, bookmark.startOffset);
    range.setEnd(endNode, bookmark.endOffset);
  } catch {
    return false;
  }

  setRange(range);
  return true;
}
