import type { Editor } from '../core/Editor';

export interface MenuItemDef {
  label: string;
  // Either a direct command to fire on click, or a custom action (e.g.
  // opening a dialog/picker) — exactly one should be set.
  command?: string;
  commandValue?: string;
  action?: (editor: Editor, itemEl: HTMLElement) => void;
  separator?: boolean;
  submenu?: MenuItemDef[];
  isActive?: (editor: Editor) => boolean;
}

export interface MenuDef {
  label: string;
  items: MenuItemDef[];
}

// A TinyMCE-style menu bar: top-level labels (File/Edit/View/...), each
// opening a dropdown of items on click. Items can nest one level of
// submenu (opened on hover, to the right of the parent item). Entirely
// additive to the toolbar — every action here also exists as a toolbar
// button/select; this just gives the same commands a second, menu-shaped
// entry point.
export class MenuBar {
  readonly el: HTMLElement;
  private openMenu: HTMLElement | null = null;

  constructor(private editor: Editor, private menus: MenuDef[]) {
    this.el = document.createElement('div');
    this.el.className = 'omar-text-editor-menubar';
    this.el.setAttribute('role', 'menubar');

    this.menus.forEach((menu) => this.el.appendChild(this.renderMenuLabel(menu)));

    document.addEventListener('mousedown', this.handleOutsideClick);
    document.addEventListener('keydown', this.handleKeydown);
  }

  private renderMenuLabel(menu: MenuDef): HTMLElement {
    const label = document.createElement('button');
    label.type = 'button';
    label.className = 'omar-text-editor-menubar-label';
    label.textContent = menu.label;
    label.setAttribute('aria-haspopup', 'true');

    label.addEventListener('mousedown', (e) => e.preventDefault());
    label.addEventListener('click', () => {
      if (this.openMenu) {
        const wasThisOne = label.nextElementSibling === this.openMenu;
        this.closeAll();
        if (wasThisOne) return;
      }
      this.openDropdown(label, menu.items);
    });

    label.addEventListener('mouseenter', () => {
      // If another top-level menu is already open, hovering a sibling
      // label switches to it directly (matches native menu bar UX).
      if (this.openMenu) {
        this.closeAll();
        this.openDropdown(label, menu.items);
      }
    });

    return label;
  }

  private openDropdown(anchor: HTMLElement, items: MenuItemDef[]): void {
    const dropdown = this.buildDropdown(items, 0);
    anchor.insertAdjacentElement('afterend', dropdown);
    const rect = anchor.getBoundingClientRect();
    dropdown.style.left = `${rect.left}px`;
    dropdown.style.top = `${rect.bottom}px`;
    this.openMenu = dropdown;
  }

  private buildDropdown(items: MenuItemDef[], depth: number): HTMLElement {
    const dropdown = document.createElement('div');
    dropdown.className = 'omar-text-editor-menubar-dropdown';
    dropdown.style.position = 'fixed';
    dropdown.style.zIndex = String(1000 + depth);

    for (const item of items) {
      if (item.separator) {
        const sep = document.createElement('div');
        sep.className = 'omar-text-editor-menubar-separator';
        dropdown.appendChild(sep);
        continue;
      }

      const entry = document.createElement('button');
      entry.type = 'button';
      entry.className = 'omar-text-editor-menubar-item';
      entry.textContent = item.label;
      if (item.isActive?.(this.editor)) entry.classList.add('is-active');

      if (item.submenu) {
        entry.classList.add('has-submenu');
        let submenuEl: HTMLElement | null = null;
        entry.addEventListener('mouseenter', () => {
          submenuEl?.remove();
          submenuEl = this.buildDropdown(item.submenu!, depth + 1);
          entry.appendChild(submenuEl);
          const rect = entry.getBoundingClientRect();
          submenuEl.style.left = `${rect.right}px`;
          submenuEl.style.top = `${rect.top}px`;
        });
        entry.addEventListener('mouseleave', (e) => {
          const related = e.relatedTarget as Node | null;
          if (related && submenuEl?.contains(related)) return;
          submenuEl?.remove();
          submenuEl = null;
        });
      } else {
        entry.addEventListener('mousedown', (e) => e.preventDefault());
        entry.addEventListener('click', () => {
          if (item.action) {
            item.action(this.editor, entry);
          } else if (item.command) {
            this.editor.execCommand(item.command, item.commandValue);
          }
          this.closeAll();
        });
      }

      dropdown.appendChild(entry);
    }

    return dropdown;
  }

  private handleOutsideClick = (e: MouseEvent): void => {
    if (!this.openMenu) return;
    const target = e.target as Node;
    if (this.el.contains(target) || this.openMenu.contains(target)) return;
    this.closeAll();
  };

  private handleKeydown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape' && this.openMenu) this.closeAll();
  };

  private closeAll(): void {
    this.openMenu?.remove();
    this.openMenu = null;
  }

  destroy(): void {
    this.closeAll();
    document.removeEventListener('mousedown', this.handleOutsideClick);
    document.removeEventListener('keydown', this.handleKeydown);
    this.el.remove();
  }
}
