// Original formatting engine: applies/removes inline formatting and swaps
// block-level tags on the current selection, without depending on the
// deprecated/inconsistent document.execCommand API.

const INLINE_TAG_ALIASES: Record<string, string[]> = {
  strong: ['strong', 'b'],
  em: ['em', 'i'],
  u: ['u'],
  s: ['s', 'strike'],
  sup: ['sup'],
  sub: ['sub'],
  code: ['code'],
};

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestorTag(root: HTMLElement, node: Node, tags: string[]): HTMLElement | null {
  let current: Node | null = node;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE && tags.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

// Toggles an inline format (bold/italic/underline/etc.) on the current
// selection. If the selection is already wrapped in one of the tag's
// aliases, unwraps it (removes formatting); otherwise wraps the selected
// contents in a new element with `canonicalTag`.
export function toggleInline(root: HTMLElement, canonicalTag: string): void {
  const range = getRange();
  if (!range) return;

  const aliases = INLINE_TAG_ALIASES[canonicalTag] ?? [canonicalTag];
  const existing = findAncestorTag(root, range.commonAncestorContainer, aliases);

  if (existing) {
    if (range.collapsed) unwrapCollapsed(existing);
    else unwrapElement(existing);
    return;
  }

  if (range.collapsed) {
    toggleInlineAtCaret(canonicalTag, range);
    return;
  }

  const wrapper = document.createElement(canonicalTag);
  try {
    range.surroundContents(wrapper);
  } catch {
    // Range spans multiple elements (surroundContents can't handle partial
    // selections across element boundaries) — fall back to extracting and
    // re-inserting the fragment inside the wrapper.
    const fragment = range.extractContents();
    wrapper.appendChild(fragment);
    range.insertNode(wrapper);
  }

  const newRange = document.createRange();
  newRange.selectNodeContents(wrapper);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}

// A zero-width space so the new inline element isn't an empty tag a
// browser might collapse/strip, and so there's a text node to place the
// caret inside (an empty element can't hold a text-node-relative Range).
const CARET_MARKER = '​';

// Turns a format "on" at a collapsed caret (no selection) by inserting an
// empty inline element there and placing the caret inside it, so the next
// characters the user types land inside the tag — matching TinyMCE's
// "click Bold with nothing selected, then start typing bold text" UX.
function toggleInlineAtCaret(canonicalTag: string, range: Range): void {
  const wrapper = document.createElement(canonicalTag);
  const marker = document.createTextNode(CARET_MARKER);
  wrapper.appendChild(marker);
  range.insertNode(wrapper);

  const newRange = document.createRange();
  newRange.setStart(marker, marker.length);
  newRange.collapse(true);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}

// Turns a format "off" at a collapsed caret sitting inside `existing`: moves
// the caret out to just after the element rather than unwrapping it (which
// would also un-format any text already typed inside), matching the "stop
// typing bold from here on" expectation.
function unwrapCollapsed(existing: HTMLElement): void {
  const marker = document.createTextNode(CARET_MARKER);
  existing.parentNode?.insertBefore(marker, existing.nextSibling);

  const newRange = document.createRange();
  newRange.setStart(marker, 0);
  newRange.collapse(true);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}

function unwrapElement(el: HTMLElement): void {
  const parent = el.parentNode;
  if (!parent) return;

  const range = document.createRange();
  range.selectNodeContents(el);

  while (el.firstChild) parent.insertBefore(el.firstChild, el);
  parent.removeChild(el);

  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

export function isInlineActive(root: HTMLElement, canonicalTag: string): boolean {
  const range = getRange();
  if (!range) return false;
  const aliases = INLINE_TAG_ALIASES[canonicalTag] ?? [canonicalTag];
  return findAncestorTag(root, range.commonAncestorContainer, aliases) !== null;
}

const BLOCK_TAGS = ['p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'pre'];

function findBlockAncestor(root: HTMLElement, node: Node): HTMLElement | null {
  let current: Node | null = node;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE && BLOCK_TAGS.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

// Changes the block-level tag containing the caret/selection to `tag`
// (e.g. turn a <p> into an <h2>), preserving its inline content.
export function setBlockFormat(root: HTMLElement, tag: string): void {
  const range = getRange();
  if (!range) return;

  const block = findBlockAncestor(root, range.commonAncestorContainer) ?? root;
  if (block === root) return;
  if (block.tagName.toLowerCase() === tag) return;

  const replacement = document.createElement(tag);
  while (block.firstChild) replacement.appendChild(block.firstChild);
  block.parentNode?.replaceChild(replacement, block);

  const newRange = document.createRange();
  newRange.selectNodeContents(replacement);
  newRange.collapse(false);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}

export function getCurrentBlockFormat(root: HTMLElement): string | null {
  const range = getRange();
  if (!range) return null;
  const block = findBlockAncestor(root, range.commonAncestorContainer);
  return block ? block.tagName.toLowerCase() : null;
}

// Finds a <span> that exactly wraps the current selection (i.e. the
// selection's start and end containers both sit inside the same styling
// span, and that span isn't wrapping anything wider than the selection) —
// used so re-applying font-family/font-size/color on an already-styled
// selection updates that span in place instead of nesting a new one.
function findExactWrappingSpan(range: Range): HTMLSpanElement | null {
  const startEl = range.startContainer.nodeType === Node.ELEMENT_NODE
    ? range.startContainer as Element : range.startContainer.parentElement;
  const endEl = range.endContainer.nodeType === Node.ELEMENT_NODE
    ? range.endContainer as Element : range.endContainer.parentElement;
  if (!startEl || !endEl) return null;

  let span: Element | null = startEl.closest('span');
  while (span) {
    if (span.contains(endEl)) {
      if (rangeExactlySpansElement(range, span)) return span as HTMLSpanElement;
      return null;
    }
    span = span.parentElement?.closest('span') ?? null;
  }
  return null;
}

// Resolves a Range boundary (container + offset, which for an element
// container is a child index, but for a text container is a character
// index) down to the actual leaf node + offset it points at, so boundaries
// from either coordinate system can be compared directly.
function resolveLeafBoundary(container: Node, offset: number): { node: Node; offset: number } {
  if (container.nodeType === Node.TEXT_NODE) return { node: container, offset };
  const child = container.childNodes[offset];
  if (child) {
    let node = child;
    while (node.firstChild) node = node.firstChild;
    return { node, offset: 0 };
  }
  // offset is past the last child: resolve to the end of the last child.
  let node: Node = container.lastChild ?? container;
  while (node.lastChild) node = node.lastChild;
  const endOffset = node.nodeType === Node.TEXT_NODE ? (node as Text).length : node.childNodes.length;
  return { node, offset: endOffset };
}

// True if `range`'s start is at the very first offset inside `el` and its
// end is at the very last offset inside `el`.
function rangeExactlySpansElement(range: Range, el: Element): boolean {
  let firstLeaf: Node = el;
  while (firstLeaf.firstChild) firstLeaf = firstLeaf.firstChild;
  let lastLeaf: Node = el;
  while (lastLeaf.lastChild) lastLeaf = lastLeaf.lastChild;
  const lastLength = lastLeaf.nodeType === Node.TEXT_NODE
    ? (lastLeaf as Text).length
    : (lastLeaf as Element).childNodes.length;

  const start = resolveLeafBoundary(range.startContainer, range.startOffset);
  const end = resolveLeafBoundary(range.endContainer, range.endOffset);

  return start.node === firstLeaf && start.offset === 0
    && end.node === lastLeaf && end.offset === lastLength;
}

// Applies a CSS style property (color, background-color, text-align, etc.)
// to the block or inline selection as appropriate. Reuses an existing
// styling span that exactly wraps the selection rather than nesting a new
// one, so switching font/size/etc. repeatedly on the same text doesn't
// pile up spans.
export function applyInlineStyle(root: HTMLElement, prop: string, value: string): void {
  const range = getRange();
  if (!range || range.collapsed) return;

  const reusable = findExactWrappingSpan(range);
  if (reusable) {
    reusable.style.setProperty(prop, value);
    const newRange = document.createRange();
    newRange.selectNodeContents(reusable);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(newRange);
    return;
  }

  const span = document.createElement('span');
  span.style.setProperty(prop, value);

  try {
    range.surroundContents(span);
  } catch {
    const fragment = range.extractContents();
    span.appendChild(fragment);
    range.insertNode(span);
  }

  const newRange = document.createRange();
  newRange.selectNodeContents(span);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}

// Removes an inline CSS property (e.g. font-family) from every element
// touching the current selection — both ancestors (so a selection nested
// inside a styled span reverts) and descendants (so a selection spanning
// several differently-styled spans reverts all of them) — used for the
// "System Font" / "Default" choice in a style select, which should mean
// "clear this property" rather than "set it to some other value".
export function clearInlineStyle(root: HTMLElement, prop: string): void {
  const range = getRange();
  if (!range || range.collapsed) return;

  const stripAndMaybeUnwrap = (el: HTMLElement): void => {
    el.style.removeProperty(prop);
    if (el.tagName.toLowerCase() === 'span' && el.getAttribute('style') === '') {
      const parent = el.parentNode;
      if (!parent) return;
      while (el.firstChild) parent.insertBefore(el.firstChild, el);
      parent.removeChild(el);
    }
  };

  let ancestor: Node | null = range.commonAncestorContainer;
  while (ancestor && ancestor !== root.parentNode) {
    if (ancestor.nodeType === Node.ELEMENT_NODE) stripAndMaybeUnwrap(ancestor as HTMLElement);
    ancestor = ancestor.parentNode;
  }

  const container = range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
    ? (range.commonAncestorContainer as Element)
    : range.commonAncestorContainer.parentElement;
  container?.querySelectorAll<HTMLElement>('*').forEach((el) => {
    if (range.intersectsNode(el)) stripAndMaybeUnwrap(el);
  });
}

export function applyBlockStyle(root: HTMLElement, prop: string, value: string): void {
  const range = getRange();
  if (!range) return;
  const block = findBlockAncestor(root, range.commonAncestorContainer);
  if (!block) return;
  block.style.setProperty(prop, value);
}

// Sets several CSS properties on the current block in one pass (e.g. the
// four padding sides from a single "Spacing" dialog submit). Each entry is
// independent — passing only `paddingTop` leaves the block's existing
// left/right/bottom untouched, and re-submitting overwrites the same
// block's style in place rather than adding anything new, so there's no
// way for this to accumulate duplicate styling the way a wrapping element
// (e.g. applyInlineStyle's <span>) could.
export function applyBlockStyles(root: HTMLElement, styles: Record<string, string>): boolean {
  const range = getRange();
  if (!range) return false;
  const block = findBlockAncestor(root, range.commonAncestorContainer);
  if (!block) return false;
  for (const [prop, value] of Object.entries(styles)) {
    if (value) block.style.setProperty(prop, value);
    else block.style.removeProperty(prop);
  }
  return true;
}

export function getCurrentBlockStyle(root: HTMLElement, prop: string): string | null {
  const range = getRange();
  if (!range) return null;
  const block = findBlockAncestor(root, range.commonAncestorContainer);
  if (!block) return null;
  return block.style.getPropertyValue(prop) || null;
}

// Walks up from the caret/selection looking for the nearest ancestor
// element with `prop` set inline (e.g. a font-family/font-size wrapping
// <span> from applyInlineStyle), so a toolbar select can reflect it.
export function getCurrentInlineStyle(root: HTMLElement, prop: string): string | null {
  const range = getRange();
  if (!range) return null;

  let current: Node | null = range.commonAncestorContainer;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE) {
      const value = (current as HTMLElement).style.getPropertyValue(prop);
      if (value) return value;
    }
    current = current.parentNode;
  }
  return null;
}

export function clearFormatting(root: HTMLElement): void {
  const range = getRange();
  if (!range || range.collapsed) return;

  const text = range.toString();
  const startContainer = range.startContainer;
  range.deleteContents();

  // Insert the plain-text replacement as a sibling of the (now possibly
  // empty) formatting element, then prune that element if it's empty,
  // rather than inserting into the collapsed range directly — insertNode
  // on a range collapsed inside an emptied inline element would insert
  // *inside* it, defeating the point of clearing formatting.
  const originalParent: Node | null =
    startContainer.nodeType === Node.ELEMENT_NODE ? startContainer : startContainer.parentNode;

  const textNode = document.createTextNode(text);

  if (originalParent && originalParent !== root) {
    originalParent.parentNode?.insertBefore(textNode, originalParent.nextSibling);
  } else {
    range.insertNode(textNode);
  }

  // Prune now-empty inline formatting ancestors left behind by deleteContents.
  let ancestor: Node | null = originalParent;
  while (ancestor && ancestor !== root) {
    const next: Node | null = ancestor.parentNode;
    if (ancestor.nodeType === Node.ELEMENT_NODE && (ancestor as Element).childNodes.length === 0) {
      next?.removeChild(ancestor);
    }
    ancestor = next;
  }

  const newRange = document.createRange();
  newRange.selectNode(textNode);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(newRange);
}
